x_938076_backup_0_backup_scripts.script:
//update cost plan entered currency default value
var gr = new GlideRecord("sys_dictionary");
gr.addEncodedQuery("name=cost_plan^element=currency");
gr.query();
if (gr.next()) {
	gr.setValue("default_value", "javascript:new global.ProjectCurrencyUtil().getDefaultEnteredCurrency()");
	gr.update();
}

//update benefit plan entered currency default value
gr = new GlideRecord("sys_dictionary");
gr.addEncodedQuery("name=benefit_plan^element=currency");
gr.query();
if (gr.next()) {
	gr.setValue("default_value", "javascript:new global.ProjectCurrencyUtil().getDefaultEnteredCurrency()");
	gr.update();
}
